<?php
$admin_title='Inventory Reports';
require_once dirname(__DIR__).'/config/db.php';require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/auth.php';require_admin();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
if(isset($_GET['export'])&&$_GET['export']==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="inventory-movements.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','SKU','Product','Type','Quantity','Stock Before','Stock After','Reason','Reference','Recorded By']);
 $q=$pdo->prepare('SELECT created_at,sku,product_name,type,quantity,stock_before,stock_after,reason,reference_no,user_name FROM v_stock_history WHERE DATE(created_at) BETWEEN ? AND ? ORDER BY created_at DESC');$q->execute([$from,$to]);while($r=$q->fetch())fputcsv($out,$r);fclose($out);exit;
}
include '_header.php';
$sum=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='IN' THEN quantity ELSE 0 END),0) stock_in,COALESCE(SUM(CASE WHEN type='OUT' THEN quantity ELSE 0 END),0) stock_out,COUNT(*) movements FROM stock_transactions WHERE DATE(created_at) BETWEEN ? AND ?");$sum->execute([$from,$to]);$stats=$sum->fetch();
$q=$pdo->prepare('SELECT * FROM v_stock_history WHERE DATE(created_at) BETWEEN ? AND ? ORDER BY created_at DESC LIMIT 300');$q->execute([$from,$to]);$rows=$q->fetchAll();$low=$pdo->query('SELECT * FROM v_low_stock ORDER BY quantity ASC,name')->fetchAll();$value=$pdo->query("SELECT COALESCE(SUM(quantity*buying_price),0) v FROM products WHERE status='active'")->fetch()['v'];
?>
<div class="stat-grid"><div class="stat"><span>Stock In (selected dates)</span><strong><?=number_format($stats['stock_in'])?></strong></div><div class="stat"><span>Stock Out (selected dates)</span><strong><?=number_format($stats['stock_out'])?></strong></div><div class="stat"><span>Movements</span><strong><?=number_format($stats['movements'])?></strong></div><div class="stat"><span>Current Stock Value</span><strong><?=number_format((float)$value,2)?></strong></div></div>
<div class="panel"><div class="panel-head"><h2>Filter Movement Report</h2></div><form method="get" class="form-grid"><div class="form-group"><label>From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>" required></div><div class="form-group"><label>To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>" required></div><div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-filter"></i> Apply Filter</button> <button class="btn btn-ghost" type="submit" name="export" value="csv"><i class="fa-solid fa-file-csv"></i> Export CSV</button></div></form></div>
<div class="panel"><div class="panel-head"><h2>Low Stock / Reorder List</h2><span class="badge amber"><?=count($low)?> need attention</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Current Stock</th><th>Reorder Level</th><th>Unit</th><th>Action</th></tr></thead><tbody><?php foreach($low as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><span class="badge <?=$p['quantity']<=0?'red':'amber'?>"><?=$p['quantity']?></span></td><td><?=$p['minimum_stock']?></td><td><?=e($p['unit'])?></td><td><a class="btn btn-soft" href="stock.php">Add Stock</a></td></tr><?php endforeach;?><?php if(!$low):?><tr><td colspan="6">All active products are above their reorder levels.</td></tr><?php endif;?></tbody></table></div></div>
<div class="panel"><div class="panel-head"><h2>Stock Movement Details</h2><small class="muted">Showing up to 300 records for selected dates.</small></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product / SKU</th><th>Type</th><th>Qty</th><th>Before</th><th>After</th><th>Reason</th><th>Reference</th><th>User</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y H:i',strtotime($r['created_at']))?></td><td><?=e($r['product_name'])?><br><small><?=e($r['sku'])?></small></td><td><span class="badge <?=$r['type']==='IN'?'green':'amber'?>"><?=e($r['type'])?></span></td><td><?=$r['quantity']?></td><td><?=$r['stock_before']?></td><td><?=$r['stock_after']?></td><td><?=e($r['reason'])?></td><td><?=e($r['reference_no'])?></td><td><?=e($r['user_name'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9">No movements found for these dates.</td></tr><?php endif;?></tbody></table></div></div>
<?php include '_footer.php'; ?>
